import math, pathlib, sys
sys.path.insert(0, '.')
source = pathlib.Path('calc.py').read_text()
assert not any(word in source for word in ('eval(', 'exec(', 'compile(')), 'forbidden builtin'
from calc import evaluate
cases = {'1 + 2 * 3': 7, '(1 + 2) * 3': 9, '10 / 4': 2.5, '-3 + 5': 2, '2 * -(1 + 1)': -4,
         '8 - 3 - 2': 3, '2.5 * 4': 10, '  7 ': 7, '100 / 10 / 5': 2, '-(-2)': 2}
for expression, expected in cases.items():
    got = evaluate(expression)
    assert math.isclose(got, expected), (expression, got)
for bad in ['', '1 +', '(1 + 2', '1 2', '2 * * 3', '1 / 0', 'abc', ')(']:
    try:
        evaluate(bad)
    except ValueError:
        pass
    else:
        raise AssertionError(bad)

