def apply_discount(amount, percent):
    """Return amount reduced by percent, rounded to cents (half up)."""
    return round(amount * (1 - percent / 100), 2)

files.cart.py:
from pricing import apply_discount


class Cart:
    def __init__(self):
        self.items = []

    def add(self, name, price, quantity=1):
        self.items.append((name, price, quantity))

    def subtotal(self):
        return sum(price for _, price, quantity in self.items)

    def total(self, discount_percent=0):
        return apply_discount(self.subtotal(), discount_percent)

files.report.js:
function render(rows) {
  let out = '';
  out += 'NAME       QTY   PRICE\n';
  for (let i = 0; i < rows.length; i++) {
    const r = rows[i];
    let name = r.name;
    if (name.length > 10) name = name.slice(0, 9) + '~';
    while (name.length < 10) name += ' ';
    let qty = String(r.qty);
    while (qty.length < 5) qty = ' ' + qty;
    let price = (Math.round(r.price * 100) / 100).toFixed(2);
    while (price.length < 8) price = ' ' + price;
    out += name + ' ' + qty + price + '\n';
  }
  let total = 0;
  for (let i = 0; i < rows.length; i++) total += rows[i].qty * rows[i].price;
  out += 'TOTAL' + (Math.round(total * 100) / 100).toFixed(2).padStart(20) + '\n';
  return out;
}
module.exports = { render };

